import { collect, type Token, type TokenGroup } from './define';
import type { ThemeName } from './semantic';
import { type Tokens, tokens } from './tokens';

/** The theme `:root` carries before any `data-theme` attribute or preference applies. */
export const DEFAULT_THEME: ThemeName = 'day';

/** The theme a dark system preference selects while the player has not chosen one. */
export const DARK_THEME: ThemeName = 'night';

const NOTICE =
  '/* Generated by `pnpm --filter @buzzkill/ui tokens` from src/tokens/tokens.ts. Do not edit by hand. */';

/** The root while the player has not chosen a theme, so a system preference may decide. */
const UNCHOSEN = ':root:not([data-theme])';
const DARK = '(prefers-color-scheme: dark)';
const MORE_CONTRAST = '(prefers-contrast: more)';
const REDUCED_MOTION = '(prefers-reduced-motion: reduce)';
/** The root while the player has not asked for full motion, so a system preference may reduce it. */
const MOTION_NOT_FULL = ":root:not([data-motion='full'])";
/** The root when the player asked for reduced motion, whatever the system says. */
const MOTION_REDUCED = ":root[data-motion='reduced']";

/** Native controls and scrollbars follow the theme through `color-scheme`. */
const COLOR_SCHEME: Readonly<Record<ThemeName, string>> = { day: 'light', night: 'dark' };

/** One declaration line: a primitive carries its value, a higher layer a `var()` reference. */
export function declaration(token: Token, depth = 1): string {
  const value = token.ref === undefined ? token.value : `var(${token.ref.name})`;
  return `${'  '.repeat(depth)}${token.name}: ${value};`;
}

function selectorOf(theme: ThemeName): string {
  return theme === DEFAULT_THEME ? ':root' : `[data-theme='${theme}']`;
}

function colorScheme(theme: ThemeName): readonly string[] {
  return [`color-scheme: ${COLOR_SCHEME[theme]};`];
}

/**
 * One rule at the given nesting depth. `extra` lines are plain declarations; Stylelint wants an
 * empty line between the custom properties and them.
 */
function rule(
  selector: string,
  group: TokenGroup,
  depth = 0,
  extra: readonly string[] = [],
): string[] {
  const outer = '  '.repeat(depth);
  const inner = '  '.repeat(depth + 1);
  return [
    `${outer}${selector} {`,
    ...collect(group).map((token) => declaration(token, depth + 1)),
    ...(extra.length === 0 ? [] : ['', ...extra.map((line) => `${inner}${line}`)]),
    `${outer}}`,
  ];
}

function media(query: string, rules: readonly (readonly string[])[]): string[] {
  const body = rules.flatMap((lines, index) => (index === 0 ? [...lines] : ['', ...lines]));
  return [`@media ${query} {`, ...body, '}'];
}

/**
 * Renders the stylesheet of the tokens (#74, #75): every layer on `:root` with the default
 * theme's colors, each other theme as a `[data-theme]` block, the dark theme again for a dark
 * system preference while no theme is chosen, and the preference overrides for more contrast
 * and reduced motion. Motion follows the system preference unless `data-motion` on the root says
 * `full`, and `data-motion='reduced'` reduces it regardless. The output is already in the form Prettier and Stylelint keep, so the
 * committed file never changes under the hooks.
 */
export function renderTokensCss(source: Tokens = tokens): string {
  const { color, ...shared } = source.semantic;
  // `Object.keys` loses the key type; the themes object has exactly the ThemeName keys.
  const themes = Object.keys(color) as ThemeName[];
  const root: TokenGroup = {
    primitives: source.primitives,
    shared,
    color: color[DEFAULT_THEME],
    components: source.components,
  };
  const { contrastMore, reducedMotion } = source.preferences;

  const blocks = [
    rule(':root', root, 0, colorScheme(DEFAULT_THEME)),
    ...themes
      .filter((theme) => theme !== DEFAULT_THEME)
      .map((theme) => rule(selectorOf(theme), color[theme], 0, colorScheme(theme))),
    media(DARK, [rule(UNCHOSEN, color[DARK_THEME], 1, colorScheme(DARK_THEME))]),
    media(
      MORE_CONTRAST,
      themes.map((theme) => rule(selectorOf(theme), contrastMore[theme], 1)),
    ),
    media(`${MORE_CONTRAST} and ${DARK}`, [rule(UNCHOSEN, contrastMore[DARK_THEME], 1)]),
    media(REDUCED_MOTION, [rule(MOTION_NOT_FULL, reducedMotion, 1)]),
    rule(MOTION_REDUCED, reducedMotion, 0),
  ];
  return `${[NOTICE, ...blocks.map((lines) => lines.join('\n'))].join('\n\n')}\n`;
}
